INSERT INTO articles (
  slug, title, category_slug, organization, job_type, location,
  qualification, salary, last_date, publish_date, official_link,
  featured, logo_initial, excerpt, content, seo_title, meta_description,
  status, featured_image, image_alt, experience, positions, apply_link,
  is_verified, focus_keyword, canonical_url, og_title, og_description
) VALUES (
  'hec-jobs-2026',
  'HEC Jobs 2026 – 9 Government Vacancies, Apply Before October 14',
  'government-jobs',
  'Higher Education Commission (HEC) Pakistan',
  'Government Regular & Project Contract Vacancies (9 Positions)',
  'HEC Head Office, Islamabad / Provincial Quotas',
  'Primary / Matric / Bachelor''s (BA/BSc/BCom/BBA) / Master''s / LLB / PhD',
  'Rs. 40,700 – Rs. 398,130 per month (BPS-01 to PPS-10)',
  '2026-10-14',
  '2026-10-06',
  'https://careers.hec.gov.pk/',
  1,
  'HEC',
  'Higher Education Commission (HEC) Pakistan invites online applications for 9 government vacancies including Project Director, Project Managers, Law Officer, Project Accountant, Office Assistants, and Attendant. Monthly salary ranges from Rs40,700 to Rs398,130. Apply before 14 October 2026.',
  '["### Executive Recruitment Notice & Official Announcement","The **Higher Education Commission (HEC) Pakistan**, the apex statutory federal regulatory body governing higher education in Pakistan, has released its official recruitment advertisement for **9 government vacancies** across federal project scales and regular basic pay scales. Qualified professionals from across Pakistan are invited to submit digital applications via the official HEC recruitment portal (`careers.hec.gov.pk`).","All nine positions are currently active and accepting online submissions until the strict closing deadline of **14 October 2026**.","### Comprehensive Breakdown of 9 Active Positions","Below is the complete, officially verified summary table specifying each of the 9 positions, quota allocation, required qualifications, exact monthly salary scales, and closing deadlines:\n\n| Position Title | Vacancies | Regional Quota | Prescribed Qualification & Experience | Monthly Salary Scale | Application Deadline |\n| :--- | :---: | :--- | :--- | :--- | :---: |\n| **Project Director** | 01 | Open Merit | PhD / Master''s (16/18 Years) in Management Sciences, Engineering, or Social Sciences with 10+ years executive project management experience | **PPS-10 (Rs. 350,000 – Rs. 398,130 / month)** | 14 October 2026 |\n| **Project Manager** | 01 | Open Merit | Master''s degree or 16-year BS in Management, CS, or Engineering with minimum 5 years proven project administration experience | **PPS-08 (Rs. 175,000 – Rs. 218,970 / month)** | 14 October 2026 |\n| **Project Manager** | 01 | Punjab Quota | Master''s degree or 16-year BS in relevant discipline with minimum 5 years project coordination experience | **PPS-08 (Rs. 175,000 – Rs. 218,970 / month)** | 14 October 2026 |\n| **Project Manager** | 01 | Khyber Pakhtunkhwa (KPK) | Master''s degree or 16-year BS with 5 years project monitoring & execution experience | **PPS-08 (Rs. 175,000 – Rs. 218,970 / month)** | 14 October 2026 |\n| **Law Officer** | 01 | Open Merit | Bachelor of Laws (LLB) from an HEC-recognized university with active Bar Council enrollment and 2–3 years corporate/court litigation experience | **BPS-17 (Rs. 75,000 – Rs. 95,000+ / month)** | 14 October 2026 |\n| **Project Accountant** | 01 | Sindh (Urban) Quota | B.Com / BBA Finance / M.Com / BS Accounting & Finance with 2+ years public/private financial accounting and audit experience | **Project Pay Scale (Rs. 80,000 – Rs. 110,000 / month)** | 14 October 2026 |\n| **Office Assistant** | 01 | Punjab Quota | Bachelor''s Degree (BA / B.Sc / B.Com / BBA) with proven computer literacy (MS Office) and minimum typing speed | **BPS-15 (Rs. 50,000 – Rs. 65,000+ / month)** | 14 October 2026 |\n| **Office Assistant** | 01 | Sindh (Rural) Quota | Bachelor''s Degree (BA / B.Sc / B.Com / BBA) with MS Office proficiency and clerical management skills | **BPS-15 (Rs. 50,000 – Rs. 65,000+ / month)** | 14 October 2026 |\n| **Attendant** | 01 | Open Merit / Punjab Quota | Primary / Matriculation with physical fitness, reliability, and office dispatch/hospitality experience | **BPS-01 (Rs. 40,700 / month basic + allowances)** | 14 October 2026 |","### Verified Salary & Scale Structure Breakdown","> [!NOTE]\n> **Official Pay Scale Structure:** The advertised positions fall within the verified salary spectrum of **Rs. 40,700 up to Rs. 398,130 per month**:\n> - **Executive Leadership (PPS-10):** Fixed Project Pay Scale offering total monthly emoluments ranging from Rs. 350,000 to Rs. 398,130 based on candidate experience.\n> - **Mid-Level Project Management (PPS-08):** Fixed Project Pay Scale offering total monthly emoluments between Rs. 175,000 and Rs. 218,970.\n> - **Officer & Specialized Roles (BPS-17 & Project Accountant):** Ranging between Rs. 75,000 and Rs. 110,000 including standard federal allowances.\n> - **Secretarial & Support Roles (BPS-15):** Basic Pay Scale 15 with allowances totaling Rs. 50,000 to Rs. 65,000.\n> - **Office Attendant (BPS-01):** Entry-level federal basic pay scale with cost of living and utility allowances totaling Rs. 40,700 per month.","### Contract Nature & Age Limit Specifications","- **Nature of Appointments:** Project positions (PPS-10, PPS-08, and Project Accountant) are contractual appointments for an initial period of one year, extendable subject to satisfactory performance and project duration. Regular BPS positions (BPS-17, BPS-15, BPS-01) follow standard federal employment rules.\n- **Age Limits (Calculated as of 14 October 2026):**\n  * Project Director: 35 to 50 Years\n  * Project Managers: 25 to 40 Years\n  * Law Officer & Project Accountant: 22 to 35 Years\n  * Office Assistants: 18 to 30 Years\n  * Attendant: 18 to 30 Years\n  * Standard general age relaxation of 5 years is admissible under Federal Government rules.","### Provincial & Regional Representation Focus","The recruitment strictly enforces constitutional provincial quota allocations:\n- **Sindh Representation:** 1 position of Office Assistant is exclusively reserved under **Sindh (Rural)** quota, and 1 position of Project Accountant is reserved under **Sindh (Urban)** quota.\n- **Punjab Representation:** 2 positions (1 Office Assistant, 1 Project Manager) and 1 Attendant are allocated under Punjab quota.\n- **Khyber Pakhtunkhwa Representation:** 1 Project Manager position is exclusively reserved for KPK domicile holders.\n- **Open Merit:** Project Director, 1 Project Manager, and Law Officer are open to all Pakistani nationals regardless of provincial domicile.","### Application Fee & Payment Mode","- A non-refundable application processing fee is prescribed:\n  * **BPS-01 to BPS-15:** Rs. 600\n  * **BPS-17 and PPS Roles:** Rs. 1,000\n- Fee must be deposited online through **1Link 1Bill Invoice** via ATM, Internet Banking, Mobile Banking Apps (Easypaisa/JazzCash/Bank apps), using the dedicated consumer number generated automatically upon submitting the profile on `careers.hec.gov.pk`.\n- Retain the transaction ID and paid receipt for interview verification.","### Selection Process & Testing Criteria","1. **Initial Screening:** Shortlisting of candidates based on academic credentials, domicile eligibility, and requisite years of experience.\n2. **Written Screening Test:** Eligible candidates for clerical and officer posts will appear in a screening test conducted by the Education Testing Council (ETC) or HEC testing committee.\n3. **Interview Panel:** Shortlisted candidates will be invited for interview at HEC Head Office, Sector H-9, Islamabad.","### Required Documents for Online Upload","- CNIC Copy (Front & Back)\n- Provincial Domicile Certificate\n- All Academic Certificates, Degrees, and Detailed Marks Certificates (DMCs) from Matric to highest degree\n- Verified Experience Letters from past and present employers\n- Valid Bar Council License / Enrollment Certificate (Mandatory for Law Officer)\n- Recent passport-size photograph with blue or white background","### Step-by-Step Online Application Procedure","1. Navigate to the official HEC recruitment portal: `https://careers.hec.gov.pk/`.\n2. Click on **Sign Up** to create an account using your 13-digit CNIC number and a valid email address.\n3. Complete your digital profile: Personal Details, Educational History, and Employment Experience.\n4. Browse the active vacancies list and choose the position aligned with your qualification and quota.\n5. Generate the 1Link 1Bill invoice and pay the fee through your mobile banking application.\n6. Confirm payment status on the portal, review all entered records, and click **Submit Application**.\n7. Download and print the electronic application form before **14 October 2026**.","### Frequently Asked Questions (FAQ)","**Q1: What is the deadline to apply for HEC Jobs 2026?**\nThe final deadline for digital application submission on `careers.hec.gov.pk` is **14 October 2026**.\n\n**Q2: Can I apply for more than one vacancy?**\nYes. Candidates possessing the required eligibility criteria for multiple posts can submit separate applications and pay the respective processing fees for each position.\n\n**Q3: Is hardcopy submission to HEC Islamabad required?**\nNo. Do not dispatch physical application copies by post. Only candidates shortlisted for test or interview will be asked to present original verified documents.\n\n**Q4: Are government employees eligible to apply?**\nYes, serving government employees can apply online but must obtain a Departmental Permission Certificate (NOC) from their parent department before appearing for the interview."]',
  'HEC Jobs 2026 – 9 Government Vacancies, Apply Before October 14 | CareerDost',
  'HEC Jobs 2026: Apply online for 9 government vacancies at careers.hec.gov.pk before 14 October 2026. Detailed salary breakdown (Rs40,700 to Rs398,130/month), quotas, eligibility, and step-by-step procedure.',
  'published',
  '/images/hec-jobs-2026.svg',
  'HEC Jobs 2026 9 Government Vacancies Apply Online Before October 14 careers hec gov pk',
  'Fresh to 10+ Years (Post-Specific Requirements)',
  '9 Vacancies (Merit, Punjab, KPK & Sindh Quotas)',
  'https://careers.hec.gov.pk/',
  1,
  'HEC Jobs 2026',
  'https://careerdost.blog/jobs/hec-jobs-2026',
  'HEC Jobs 2026 – 9 Government Vacancies, Apply Before October 14',
  'Higher Education Commission (HEC) recruitment for 9 government positions across PPS and BPS pay scales (Rs40,700 – Rs398,130/month). Apply online via careers.hec.gov.pk by 14 October 2026.'
)
